#!/bin/sh
# ==============================================================================
# JunWRT WebUI & Commercial Activation Hot-Deployer for AW1000 Stock Firmware
# Deploys Cockpit, Pure White WebUI, SSH Banner, Hostname & Cryptographic Licensing
# ==============================================================================

echo "=================================================================="
echo " [*] Installing JunWRT Cockpit, WebUI & Commercial Activation...  "
echo "=================================================================="

# 1. Prepare target directories
mkdir -p /www/luci-static/resources/view/modem
mkdir -p /www/luci-static/resources/view/status/include
mkdir -p /www/luci-static/resources/view/system
mkdir -p /www/luci-static/argon/img
mkdir -p /www/luci-static/argon/css
mkdir -p /www/luci-static/resources/icons
mkdir -p /usr/lib/lua/luci/view/themes/argon
mkdir -p /usr/lib/lua/luci/controller
mkdir -p /usr/lib/lua/luci/view/admin_mtk
mkdir -p /usr/share/luci/menu.d
mkdir -p /usr/share/3ginfo-lite/modem/mtk/fibocom
mkdir -p /usr/share/rpcd/acl.d
mkdir -p /usr/bin
mkdir -p /etc/init.d
mkdir -p /etc/rc.d

TMP_TAR="/tmp/junwrt_webui_lic.tar.gz"

cat << 'EOF_PAYLOAD' | base64 -d > "$TMP_TAR"

EOF_PAYLOAD

if [ ! -s "$TMP_TAR" ]; then
    echo "[-] ERROR: Failed to decode installer archive."
    rm -f "$TMP_TAR"
    exit 1
fi

echo " [*] Extracting views, themes, SSH banner and licensing engine..."
tar -xzf "$TMP_TAR" -C / 2>/dev/null
rm -f "$TMP_TAR"

# 2. Set execution permissions
chmod 0755 /usr/bin/junwrt-license 2>/dev/null || true
chmod 0755 /etc/init.d/junwrt-license 2>/dev/null || true
chmod 0755 /etc/rc.d/S98junwrt-license 2>/dev/null || true
chmod 0755 /usr/share/3ginfo-lite/3ginfo.sh 2>/dev/null || true

# 3. Set Hostname to JunWRT (Updates root@JunWRT in SSH & WebUI)
echo " [*] Updating System Hostname to JunWRT..."
uci set system.@system[0].hostname='JunWRT' 2>/dev/null || true
uci commit system 2>/dev/null || true
echo "JunWRT" > /proc/sys/kernel/hostname 2>/dev/null || true

# 4. Initialize Machine ID & Licensing Service
[ -s /etc/junwrt_machine_id ] || /usr/bin/junwrt-license machine-id > /etc/junwrt_machine_id 2>/dev/null || true
chmod 0644 /etc/junwrt_machine_id 2>/dev/null || true
/etc/init.d/junwrt-license enable 2>/dev/null || true
/etc/init.d/junwrt-license restart 2>/dev/null || true

# 5. Set Argon as default theme
uci set luci.main.mediaurlbase='/luci-static/argon' 2>/dev/null || true
uci commit luci 2>/dev/null || true

# 6. Clean conflicting legacy files
rm -f /www/luci-static/resources/view/status/include/25_traffic_wifi.js 2>/dev/null || true

# 7. Flush LuCI cache & reload web server
echo " [*] Flushing LuCI cache & restarting web server..."
rm -rf /tmp/luci-indexcache /tmp/luci-modulecache
/etc/init.d/uhttpd restart 2>/dev/null || true

echo "=================================================================="
echo " [+] SUCCESS: JunWRT Cockpit & Activation System installed!       "
echo " [+] Hostname: JunWRT (Prompt will show root@JunWRT)              "
echo " [+] Machine ID: $(cat /etc/junwrt_machine_id 2>/dev/null || echo 'Check in WebUI')"
echo " [+] Open http://192.168.1.1 (System -> Activation & License)    "
echo "=================================================================="
exit 0
